def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max((v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    sep_cols = [c for c in range(w) if all(grid[r][c] != bg for r in range(h))]
    if not sep_rows or not sep_cols:
        return grid

    vc = sep_cols[0]
    bands = []
    start = 0
    for r in sep_rows:
        bands.append((start, r))
        start = r + 1
    bands.append((start, h))

    # The band containing the pattern is copied into every band.
    source = max(bands, key=lambda ab: sum(
        grid[r][c] != bg
        for r in range(ab[0], ab[1])
        for c in range(vc + 1, w)
    ))
    out = [row[:] for row in grid]
    for a, b in bands:
        for i, r in enumerate(range(a, b)):
            sr = source[0] + (i % (source[1] - source[0]))
            for c in range(vc + 1, w):
                out[r][c] = grid[sr][c]
            for c in range(vc):
                out[r][c] = grid[sr][vc + 1 + c]
    return out
